[
  {
    "operation": "shift",
    "spec": {
      "customer": {
        "name": "fullName",
        "id": "custId"
      }
    }
  }
]

[
  {
    "operation": "default",
    "spec": {
      "ingestedAt": "${now():toNumber()}",
      "source": "nexus-flow"
    }
  }
]

{
  "nodes": [
    {
      "id": "u",
      "type": "nifi.UpdateAttribute",
      "params": {
        "region": "US"
      }
    },
    {
      "id": "j",
      "type": "nifi.EvaluateJsonPath",
      "params": {
        "orderId": "$.id"
      }
    },
    {
      "id": "r",
      "type": "nifi.RouteOnAttribute",
      "params": {
        "premium": "${tier} == 'GOLD'"
      }
    }
  ],
  "edges": [
    {
      "source": "u",
      "target": "j",
      "relationship": "success"
    },
    {
      "source": "j",
      "target": "r",
      "relationship": "success"
    }
  ]
}

{
  "nodes": [
    {
      "id": "jolt",
      "type": "nifi.JoltTransformJSON",
      "params": {
        "Jolt Specification": "[{\"operation\":\"shift\",\"spec\":{\"payload\":\"data\"}}]"
      }
    },
    {
      "id": "conv",
      "type": "nifi.ConvertRecord",
      "params": {
        "Record Reader": "json",
        "Record Writer": "csv"
      }
    }
  ],
  "edges": [
    {
      "source": "jolt",
      "target": "conv",
      "relationship": "success"
    }
  ]
}
